<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('inventory.view');
$q=trim((string)($_GET['q']??''));$type=(string)($_GET['type']??'');$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$page=max(1,(int)($_GET['page']??1));$per=40;$where=['1=1'];$params=[];if($q!==''){$where[]='(p.name LIKE :q OR p.sku LIKE :q OR sm.reference_no LIKE :q)';$params[':q']='%'.$q.'%';}$types=['opening_stock','purchase','sale','customer_return','supplier_return','damage','loss','adjustment_in','adjustment_out','void_reversal','transfer_in','transfer_out'];if(in_array($type,$types,true)){$where[]='sm.movement_type=:type';$params[':type']=$type;}if($from!==''){$where[]='sm.created_at>=:from';$params[':from']=$from.' 00:00:00';}if($to!==''){$where[]='sm.created_at<DATE_ADD(:to,INTERVAL 1 DAY)';$params[':to']=$to.' 00:00:00';}$ws=implode(' AND ',$where);$c=db()->prepare("SELECT COUNT(*) FROM stock_movements sm INNER JOIN products p ON p.id=sm.product_id WHERE $ws");$c->execute($params);$total=(int)$c->fetchColumn();$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$off=($page-1)*$per;$st=db()->prepare("SELECT sm.*,p.name product_name,p.sku,u.short_name,usr.full_name FROM stock_movements sm INNER JOIN products p ON p.id=sm.product_id INNER JOIN units u ON u.id=p.unit_id INNER JOIN users usr ON usr.id=sm.created_by WHERE $ws ORDER BY sm.id DESC LIMIT $per OFFSET $off");$st->execute($params);$rows=$st->fetchAll();
$pageTitle='Stock Movements';$pageStyles=['admin.css','commerce.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="content"><div class="page-toolbar"><div><a class="back-link" href="<?=e(app_url('inventory/index'))?>">← Inventory</a><h2>Stock movements</h2><p>Permanent transaction history for every stock change.</p></div></div><section class="panel-card table-panel"><form class="filter-bar" method="get"><div class="filter-search"><input name="q" value="<?=e($q)?>" placeholder="Product, SKU or reference"></div><select name="type"><option value="">All movements</option><?php foreach($types as$t):?><option value="<?=e($t)?>" <?=$type===$t?'selected':''?>><?=e(ucwords(str_replace('_',' ',$t)))?></option><?php endforeach;?></select><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><button class="button button--secondary">Filter</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Product</th><th>Movement</th><th>Change</th><th>Before</th><th>After</th><th>Reference</th><th>User</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8"><div class="empty-state"><strong>No movements found</strong></div></td></tr><?php else:foreach($rows as$r):?><tr><td><?=e(format_datetime($r['created_at']))?></td><td><strong><?=e($r['product_name'])?></strong><small class="table-note"><?=e($r['sku'])?></small></td><td><?=e(ucwords(str_replace('_',' ',$r['movement_type'])))?></td><td class="<?=((float)$r['quantity_change']>=0?'text-success':'text-danger')?>"><?=((float)$r['quantity_change']>=0?'+':'')?><?=e(format_quantity($r['quantity_change']))?> <?=e($r['short_name'])?></td><td><?=e(format_quantity($r['stock_before']))?></td><td><?=e(format_quantity($r['stock_after']))?></td><td><?=e($r['reference_no']?:'—')?></td><td><?=e($r['full_name'])?></td></tr><?php endforeach;endif;?></tbody></table></div><div class="table-footer"><span><?=$total?> movement(s)</span></div></section></main></div><?php require BASE_PATH.'/includes/footer.php';?>
